  1	using System.Diagnostics;
  2	using System.IO;
  3	using LoadOrderKeeper.Models;
  4	
  5	namespace LoadOrderKeeper.Services
  6	{
  7	    public static class DiffService
  8	    {
  9	        private static readonly ViewTexts.LocalizationService _localization = ViewTexts.LocalizationService.Instance;
 10	
 11	        public static async Task<IReadOnlyList<DiffLineModel>> GetPluginsDiffAsync(AppConfigModel config)
 12	        {
 13	            if (config is null)
 14	            {
 15	                throw new ArgumentNullException(nameof(config));
 16	            }
 17	
 18	            if (!config.IsValid())
 19	            {
 20	                throw new InvalidOperationException("Configuration paths are invalid.");
 21	            }
 22	
 23	            string targetPath = config.GetPluginsFilePath();
 24	            string referencePath = config.GetReferenceFilePath();
 25	
 26	            if (!File.Exists(referencePath))
 27	            {
 28	                throw new FileNotFoundException("Reference file not found.", referencePath);
 29	            }
 30	
 31	            if (!File.Exists(targetPath))
 32	            {
 33	                throw new FileNotFoundException("Plugins file not found.", targetPath);
 34	            }
 35	
 36	            var referenceMods = await FileService.ReadModListAsync(referencePath, isReferenceFile: true).ConfigureAwait(false);
 37	            var currentMods   = await FileService.ReadModListAsync(targetPath).ConfigureAwait(false);
 38	
 39	            var refFileNames = referenceMods.Select(m => m.FileName).ToList();
 40	            var curFileNames = currentMods.Select(m => m.FileName).ToList();
 41	
 42	            var lcs = ComputeLcs(refFileNames, curFileNames, StringComparer.OrdinalIgnoreCase);
 43	
 44	            return ClassifyChanges(referenceMods, currentMods, lcs);
 45	        }
 46	
 47	        /// <summary>
 48	        /// Checks if there are any moved mods that are NOT part of dependent change lists.
 49	        /// These independent moves indicate external reordering that sorting could fix.
 50	        /// </summary>
 51	        public static async Task<bool> HasIndependentMovedModsAsync(AppConfigModel config)
 52	        {
 53	            if (config is null)
 54	            {
 55	                throw new ArgumentNullException(nameof(config));
 56	            }
 57	
 58	            if (!config.IsValid())
 59	            {
 60	                return false;
 61	            }
 62	
 63	            string targetPath = config.GetPluginsFilePath();
 64	            string referencePath = config.GetReferenceFilePath();
 65	
 66	            if (!File.Exists(referencePath) || !File.Exists(targetPath))
 67	            {
 68	                return false;
 69	            }
 70	
 71	            var diffLines = await GetPluginsDiffAsync(config).ConfigureAwait(false);
 72	            
 73	            // Get all mods that are part of dependent change lists
 74	            var dependentMods = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 75	            foreach (var line in diffLines)
 76	            {
 77	                foreach (var dependent in line.DependentChanges)
 78	                {
 79	                    dependentMods.Add(dependent.FileName);
 80	                }
 81	            }
 82	            
 83	            // Check if there are any moved mods that are NOT in the dependent set
 84	            bool hasIndependentMoves = diffLines.Any(line => 
 85	                line.ChangeType == DiffChangeType.Moved && 
 86	                !dependentMods.Contains(line.FileName));
 87	            
 88	            return hasIndependentMoves;
 89	        }
 90	
 91	        /// <summary>
 92	        /// Computes the Longest Common Subsequence of two string lists using a standard
 93	        /// dynamic-programming approach. Returns a list of paired (refIndex, curIndex) tuples
 94	        /// representing the LCS in order, where refIndex is the position in
 95	        /// <paramref name="reference"/> and curIndex is the position in <paramref name="current"/>.
 96	        /// </summary>
 97	        internal static List<(int refIndex, int curIndex)> ComputeLcs(
 98	            IReadOnlyList<string> reference,
 99	            IReadOnlyList<string> current,
100	            StringComparer comparer)

101	        {
102	            int m = reference.Count;
103	            int n = current.Count;
104	
105	            // Build DP table
106	            var dp = new int[m + 1, n + 1];
107	            for (int i = 1; i <= m; i++)
108	            {
109	                for (int j = 1; j <= n; j++)
110	                {
111	                    if (comparer.Equals(reference[i - 1], current[j - 1]))
112	                    {
113	                        dp[i, j] = dp[i - 1, j - 1] + 1;
114	                    }
115	                    else
116	                    {
117	                        dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j - 1]);
118	                    }
119	                }
120	            }
121	
122	            // Backtrack to recover the LCS pairs
123	            var result = new List<(int refIndex, int curIndex)>(dp[m, n]);
124	            int ri = m, ci = n;
125	            while (ri > 0 && ci > 0)
126	            {
127	                if (comparer.Equals(reference[ri - 1], current[ci - 1]))
128	                {
129	                    result.Add((ri - 1, ci - 1));
130	                    ri--;
131	                    ci--;
132	                }
133	                else if (dp[ri - 1, ci] >= dp[ri, ci - 1])
134	                {
135	                    ri--;
136	                }
137	                else
138	                {
139	                    ci--;
140	                }
141	            }
142	
143	            result.Reverse();
144	            return result;
145	        }
146	
147	        /// <summary>
148	        /// Classifies changes between <paramref name="reference"/> and <paramref name="current"/>
149	        /// mod lists given the pre-computed LCS alignment. Returns a flat list of
150	        /// <see cref="DiffLineModel"/> entries (dependents are nested under their causal change).
151	        /// </summary>
152	        /// <remarks>
153	        /// Classification pipeline (Steps 0–6, matching the inline step comments in the implementation):
154	        /// <list type="bullet">
155	        ///   <item><b>Step 0</b> — Build fast lookup sets: partition reference and current items into LCS
156	        ///         members (unchanged), removed candidates (reference only), and new candidates (current only).</item>
157	        ///   <item><b>Step 1</b> — Identify shifted LCS items: LCS members whose absolute positions differ
158	        ///         between the two lists → candidate dependent changes (Moved).</item>
159	        ///   <item><b>Step 2</b> — Same-filename reconciliation: removed mod whose filename also appears in
160	        ///         the new set → Moved (swapped); performed before replacement detection.</item>
161	        ///   <item><b>Step 3</b> — Replacement detection: removed item at reference position R paired with
162	        ///         the new item at the corresponding LCS-aligned current position → Replaced.</item>
163	        ///   <item><b>Step 4</b> — Remaining new items classified as Added (beyond all surviving reference
164	        ///         mods) or Inserted (within the range of surviving reference mods).</item>
165	        ///   <item><b>Step 5</b> — Build the top-level result list: emit Moved (from Step 2), Replaced,
166	        ///         Removed, Added/Inserted entries in a single flat pass.</item>
167	        ///   <item><b>Step 6</b> — Group shifted LCS items as dependent changes under their causal
168	        ///         insertion/deletion and remove them from the top-level list.</item>
169	        /// </list>
170	        /// </remarks>
171	        internal static List<DiffLineModel> ClassifyChanges(
172	            IReadOnlyList<ModEntryModel> reference,
173	            IReadOnlyList<ModEntryModel> current,
174	            List<(int refIndex, int curIndex)> lcs)
175	        {
176	            // --- Step 0: Build fast lookup sets ---
177	            var lcsRefIndices = new HashSet<int>();
178	            var lcsCurIndices = new HashSet<int>();
179	            foreach (var (ri, ci) in lcs)
180	            {
181	                lcsRefIndices.Add(ri);
182	                lcsCurIndices.Add(ci);
183	            }
184	
185	            // Items in reference not in LCS → Removed candidates
186	            var removedMods = new List<ModEntryModel>();
187	            for (int i = 0; i < reference.Count; i++)
188	            {
189	                if (!lcsRefIndices.Contains(i))
190	                {
191	                    removedMods.Add(reference[i]);
192	                }
193	            }
194	
195	            // Items in current not in LCS → New candidates
196	            var newMods = new List<ModEntryModel>();
197	            for (int j = 0; j < current.Count; j++)
198	            {
199	                if (!lcsCurIndices.Contains(j))
200	                {
201	                    newMods.Add(current[j]);
202	                }
203	            }
204	
205	            // --- Step 1: LCS-shifted items (same relative order, different absolute position) ---
206	            // These are the "moved due to neighbour insertion/deletion" entries that will become
207	            // dependent changes. We track them but don't emit them as top-level entries yet.
208	            var lcsShifted = new List<(ModEntryModel mod, int refPos, int curPos)>();
209	            foreach (var (ri, ci) in lcs)
210	            {
211	                // Invariant: FileService.ReadFileAsync always assigns LineNumber for every entry it
212	                // produces, so these values should never be null at this point.  The ?? fallbacks
213	                // below are purely defensive — they use the 1-based LCS index as a proxy position
214	                // so that shift detection can still run rather than crashing if the invariant is
215	                // ever violated.
216	                Debug.Assert(reference[ri].LineNumber.HasValue, $"reference[{ri}].LineNumber must be set — FileService.ReadFileAsync guarantees LineNumber is populated for every entry.");
217	                Debug.Assert(current[ci].LineNumber.HasValue,   $"current[{ci}].LineNumber must be set — FileService.ReadFileAsync guarantees LineNumber is populated for every entry.");
218	                int refPos = reference[ri].LineNumber ?? (ri + 1);
219	                int curPos = current[ci].LineNumber ?? (ci + 1);
220	                if (refPos != curPos)
221	                {
222	                    lcsShifted.Add((reference[ri], refPos, curPos));
223	                }
224	            }
225	
226	            // --- Step 2: Same-filename reconciliation (Moved / swapped) ---
227	            var newByFilename = new Dictionary<string, ModEntryModel>(StringComparer.OrdinalIgnoreCase);
228	            foreach (var m in newMods)
229	            {
230	                newByFilename.TryAdd(m.FileName, m);
231	            }
232	
233	            var movedResults = new List<DiffLineModel>();
234	            var reconciledRemovedFilenames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
235	            // ReferenceEqualityComparer.Instance is intentional: ModEntryModel.Equals() compares by
236	            // FileName, so the default comparer would incorrectly de-duplicate two distinct instances
237	            // with the same filename. Identity comparison ensures we track the exact objects matched.
238	            var reconciledNewMods = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
239	
240	            foreach (var removed in removedMods)
241	            {
242	                if (newByFilename.TryGetValue(removed.FileName, out var matchingNew))
243	                {
244	                    // Same filename appeared in both removed and new → swapped/moved
245	                    string text = _localization.GetString("DiffDialog", "MovedText_Description",
246	                        removed.FileName,
247	                        removed.LineNumber ?? 0,
248	                        matchingNew.LineNumber ?? 0);
249	                    movedResults.Add(new DiffLineModel(
250	                        removed.FileName, text, DiffChangeType.Moved,

251	                        removed.LineNumber, matchingNew.LineNumber));
252	
253	                    reconciledRemovedFilenames.Add(removed.FileName);
254	                    reconciledNewMods.Add(matchingNew);
255	                }
256	            }
257	
258	            // Remove reconciled items from working sets
259	            var remainingRemoved = removedMods
260	                .Where(m => !reconciledRemovedFilenames.Contains(m.FileName))
261	                .ToList();
262	            var remainingNew = newMods
263	                .Where(m => !reconciledNewMods.Contains(m))
264	                .ToList();
265	
266	            // --- Step 3: Replacement detection (LCS-aligned position matching) ---
267	            // Build a map from current-list positions of new items for quick lookup
268	            var newByCurPos = new Dictionary<int, ModEntryModel>();
269	            foreach (var m in remainingNew)
270	            {
271	                // Invariant: LineNumber is always populated by FileService.ReadFileAsync.
272	                // The ?? 0 sentinel below differs from the Step 1 fallback (which uses ri+1/ci+1
273	                // as a proxy position) because here we need a value that is *outside* the valid
274	                // line-number range so the entry is naturally excluded from position-based
275	                // replacement matching and falls through to be classified as Added.
276	                Debug.Assert(m.LineNumber.HasValue, $"remainingNew entry '{m.FileName}' must have LineNumber set — FileService.ReadFileAsync guarantees LineNumber is populated for every entry.");
277	                int pos = m.LineNumber ?? 0;
278	                // pos == 0 means LineNumber was null (no position assigned); skip — these entries
279	                // cannot participate in replacement matching and will be classified as Added.
280	                if (pos > 0 && !newByCurPos.ContainsKey(pos))
281	                {
282	                    newByCurPos[pos] = m;
283	                }
284	            }
285	
286	            // For each removed mod, determine its aligned current position.
287	            // The expected current position of a removed mod at reference position R is:
288	            //   R − (number of other removed mods at reference positions < R)
289	            // because each earlier deletion shifts the surviving items up by one slot.
290	
291	            // ReferenceEqualityComparer.Instance: same rationale as reconciledNewMods above —
292	            // we need object identity to avoid conflating two distinct ModEntryModel instances
293	            // that happen to share the same filename.
294	            var replacements = new Dictionary<ModEntryModel, ModEntryModel>(ReferenceEqualityComparer.Instance);
295	            var usedForReplacement = new HashSet<ModEntryModel>(ReferenceEqualityComparer.Instance);
296	
297	            // Sort removed mods by reference position for sequential processing
298	            var removedByRefPos = remainingRemoved
299	                .OrderBy(m => m.LineNumber ?? 0)
300	                .ToList();
301	
302	            int cumulativeDeletions = 0;
303	            foreach (var removed in removedByRefPos)
304	            {
305	                int refPos = removed.LineNumber ?? 0;
306	                // Aligned current position = reference position offset by the number of true
307	                // deletions that occurred before this position. Replacements do not shift
308	                // subsequent positions, so we only count unmatched removals.
309	                int alignedCurPos = refPos - cumulativeDeletions;
310	
311	                if (newByCurPos.TryGetValue(alignedCurPos, out var candidate)
312	                    && !usedForReplacement.Contains(candidate))
313	                {
314	                    replacements[removed] = candidate;
315	                    usedForReplacement.Add(candidate);
316	                    // A replacement is not a deletion: don't shift subsequent aligned positions.
317	                }
318	                else
319	                {
320	                    // True deletion — shifts subsequent positions by one.
321	                    cumulativeDeletions++;
322	                }
323	            }
324	
325	            // --- Step 4: Classify remaining new mods as Added or Inserted ---
326	            // maxSurvivingRefCurPos = highest current position of a mod that existed in reference
327	            // (either in LCS or as a moved/replacement pair)
328	            int maxSurvivingRefCurPos = 0;
329	            foreach (var (ri, ci) in lcs)
330	            {
331	                int curPos = current[ci].LineNumber ?? (ci + 1);
332	                if (curPos > maxSurvivingRefCurPos)
333	                    maxSurvivingRefCurPos = curPos;
334	            }
335	            // Also consider replacements: the replacement's current position counts as
336	            // "still within the reference range"
337	            foreach (var replacement in replacements.Values)
338	            {
339	                int curPos = replacement.LineNumber ?? 0;
340	                if (curPos > maxSurvivingRefCurPos)
341	                    maxSurvivingRefCurPos = curPos;
342	            }
343	
344	            // --- Step 5: Build the top-level result list ---
345	            var result = new List<DiffLineModel>();
346	
347	            // Replacement entries
348	            foreach (var removed in removedByRefPos)
349	            {
350	                if (replacements.TryGetValue(removed, out var replacement))
351	                {
352	                    int? lineNumber = removed.LineNumber ?? replacement.LineNumber;
353	                    string text = _localization.GetString("DiffDialog", "ReplacedText_Description",
354	                        removed.FileName, replacement.FileName, lineNumber ?? 0);
355	                    result.Add(new DiffLineModel(
356	                        removed.FileName, text, DiffChangeType.Replaced,
357	                        removed.LineNumber, replacement.LineNumber, replacement.FileName));
358	                }
359	                else
360	                {
361	                    // Truly removed
362	                    string text = _localization.GetString("DiffDialog", "RemovedText_Description",
363	                        removed.LineNumber ?? 0, removed.FileName);
364	                    result.Add(new DiffLineModel(
365	                        removed.FileName, text, DiffChangeType.Removed,
366	                        removed.LineNumber, null));
367	                }
368	            }
369	
370	            // Moved (swapped) entries
371	            result.AddRange(movedResults);
372	
373	            // Inserted / Added entries (new mods not used as replacements)
374	            foreach (var newMod in remainingNew)
375	            {
376	                if (usedForReplacement.Contains(newMod))
377	                    continue;
378	
379	                int curPos = newMod.LineNumber ?? 0;
380	                bool isInserted = curPos > 0 && curPos <= maxSurvivingRefCurPos;
381	                DiffChangeType changeType = isInserted ? DiffChangeType.Inserted : DiffChangeType.Added;
382	                string actionText = isInserted
383	                    ? _localization.GetString("DiffDialog", "InsertedText_Action")
384	                    : _localization.GetString("DiffDialog", "AddedText_Action");
385	                string text = _localization.GetString("DiffDialog", "ModChangeText_Description",
386	                    curPos, newMod.FileName, actionText);
387	                result.Add(new DiffLineModel(
388	                    newMod.FileName, text, changeType,
389	                    null, newMod.LineNumber));
390	            }
391	
392	            // LCS-shifted entries (dependent Moved)
393	            var shiftedLines = new List<DiffLineModel>();
394	            foreach (var (mod, refPos, curPos) in lcsShifted)
395	            {
